from __future__ import annotations

import asyncio
import ipaddress
import logging
from abc import ABCMeta, abstractmethod
from typing import Any, Union

from pysnmp.hlapi.asyncio import (
    UsmUserData,
    CommunityData,
    ContextData,
    ObjectIdentity,
    ObjectType,
    SnmpEngine,
    UdpTransportTarget,
    getCmd,
    setCmd,
)
from pysnmp.proto.secmod.rfc3414.auth import hmacmd5, hmacsha
from pysnmp.proto.secmod.rfc3414.priv import des
from pysnmp.proto.secmod.rfc3826.priv import aes

from taf.hw.pdu.exceptions import (
    InvalidHost,
    InvalidSnmpUser,
    PduConnectionError,
    PduVersionMismatchError,
    Timeout,
)

from .base import PDU


class SnmpPdu(PDU, metaclass=ABCMeta):
    """Class that makes it possible to manage
    a single PDU device over the SNMP protocol."""

    AUTH_PROTOCOL = {"MD5": hmacmd5.HmacMd5.serviceID, "SHA": hmacsha.HmacSha.serviceID}
    PRIV_PROTOCOL = {"DES": des.Des.serviceID, "AES": aes.Aes.serviceID}

    def __init__(
        self,
        host: str,
        timeout: Union[float, int],
        snmp_user: dict[str, Any] | None = None,
        community: str | None = None,
    ) -> None:
        """
        :param string host: IP address or domain name of PDU device.
        :param float timeout: Response timeout in seconds.
        :param dict snmp_user (required only for SNMPv3): User configuration for SNMPv3 with keys: userName, authKey,
                          privKey, authProtocol (SHA/MD5), privProtocol (AES/DES)
        :param community: Community string used by SNMPv1/2.
        """
        self._snmp_user = None
        self._init_verifiers(host, timeout, snmp_user)

        if snmp_user is not None:
            _snmp_user = snmp_user.copy()
            _snmp_user["authProtocol"] = SnmpPdu.AUTH_PROTOCOL.get(_snmp_user["authProtocol"])
            _snmp_user["privProtocol"] = SnmpPdu.PRIV_PROTOCOL.get(_snmp_user["privProtocol"])
            self._snmp_user = _snmp_user

        super().__init__(host)

        self._port = 161
        self._version: int | None = None
        self._community = community
        self._security_name = "my-agent"
        self._udp_timeout = float(timeout)
        self._snmpv3_support = self._snmp_user is not None

    @abstractmethod
    def _get_oid_value(self, action):
        """Get oid value"""

    @abstractmethod
    def _build_snmp_oid(self, port):
        """Build snmp object identifier"""

    @property
    def _auth_data(self):
        if self._snmpv3_support:
            return UsmUserData(**self._snmp_user)
        return CommunityData(self._security_name, self._community, self._version)

    def _set_port_status(self, port, status):
        snmp_msg = self._build_snmp_oid(port)
        logging.info(f"SNMP: Setting port to {status}: {port}")
        self._execute_set_cmd(status, snmp_msg)

    def get_port_status(self, port):
        logging.info(f"SNMP: Fetching status of port: {port}")
        snmp_msg = self._build_snmp_oid(port=port)
        port_value = self._execute_get_cmd(snmp_msg)
        try:
            return self._reversed_port_settings[port_value]
        except KeyError:
            logging.warning(f"empty port_value: {port_value}")
            raise PduVersionMismatchError("Declared PDU device version might differ from the actual one")

    def _execute_set_cmd(self, value, snmp_msg):
        ports_value = self._get_oid_value(value)
        asyncio.run(self._execute_cmd(setCmd, ObjectType(ObjectIdentity(snmp_msg), ports_value)))

    def _execute_get_cmd(self, snmp_msg):
        var_binds = asyncio.run(self._execute_cmd(getCmd, ObjectType(ObjectIdentity(snmp_msg))))
        return str(var_binds[0][1])

    async def _execute_cmd(self, cmd_method, object_type):
        community_data = self._auth_data
        udp_transport_target = UdpTransportTarget((self._host, self._port), timeout=self._udp_timeout)

        error_indication, error_status, error_index, var_binds = await cmd_method(
            SnmpEngine(), community_data, udp_transport_target, ContextData(), object_type
        )

        if error_status and error_indication is None:
            error_indication = f"Command not executed successfully (error status: {error_status})"
        self._verify_no_error(error_indication, error_status)
        return var_binds

    @staticmethod
    def _verify_no_error(error_indication, error_status):
        if error_status or error_indication:
            raise PduConnectionError(error_indication)

    def _verify_host(self, host):
        if host is None:
            raise InvalidHost
        if not (self._is_ip(host) or host.startswith("COM") or host.lower().endswith("nsn-rdnet.net")):
            raise InvalidHost

    def _verify_timeout(self, timeout):
        if not (isinstance(timeout, (int, float))):
            raise Timeout

    def _verify_snmp_user(self, user):
        if user is None:
            return
        keys = ["userName", "authKey", "privKey", "authProtocol", "privProtocol"]
        if not isinstance(user, dict):
            raise InvalidSnmpUser
        if set(keys) != set(user.keys()):
            raise InvalidSnmpUser
        if user["authProtocol"] not in self.AUTH_PROTOCOL or user["privProtocol"] not in self.PRIV_PROTOCOL:
            raise InvalidSnmpUser

    def _init_verifiers(self, host, timeout, user):
        self._verify_host(host)
        self._verify_timeout(timeout)
        self._verify_snmp_user(user)

    def _is_ip(self, ip_address):
        result = True
        try:
            ip_address = ip_address if isinstance(ip_address, str) else ip_address.decode("utf-8")
            ipaddress.ip_address(ip_address)
        except (ValueError, ipaddress.AddressValueError):
            result = False
        return result
